contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: caller chooses an amount to send to c.play
    function run(uint amount) public payable {
        // ensure this contract has the Ether to send
        require(address(this).balance >= amount);

        // observe before state
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after state
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint cBalAfter = address(c).balance;

        // General rule:
        // - If the call reverted: bank, pot, and contract balance are unchanged.
        // - If the call did not revert: bank remains unchanged, and the combined quantity
        //   (pot + contract balance) equals previous combined quantity plus amount,
        //   except when a payout occurred which transfers FEE_AMOUNT to bank; in that case
        //   the combined quantity increases only by (amount - FEE_AMOUNT). Because FEE_AMOUNT is 1
        //   and TICKET_AMOUNT is 10 in C, express generally as: combined after = combined before + amount
        //   OR combined after = combined before + amount - 1. We assert that one of these holds.
        assert(
            reverted
                ? (bankAfter == bankBefore && potAfter == potBefore && cBalAfter == cBalBefore)
                : (
                    bankAfter == bankBefore && (
                        // either no fee was paid (pot just increased by amount)
                        (potAfter + cBalAfter == potBefore + cBalBefore + amount) ||
                        // or a fee of 1 was paid to bank (payout happened)
                        (potAfter + cBalAfter == potBefore + cBalBefore + amount - 1)
                    )
                )
        );
    }

    // accept ETH when C sends payouts to this contract
    receive() external payable {}
}

