        uint pot_before = c.pot();
        uint bal_before = address(c).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pot_after = c.pot();
        uint bal_after = address(c).balance;

        // Read constants via public getters on c: FEE_AMOUNT and TICKET_AMOUNT are not public in C,
        // but FEE_AMOUNT and TICKET_AMOUNT are constants without getters; however we can express
        // the expected balance change in terms of pot changes and observed amounts.
        // General rule asserted below:
        // - If reverted: pot and balance unchanged.
        // - If not reverted: exactly one of two situations holds:
        //   (A) payout occurred: pot_after == 0 and bal_before - bal_after == 1 (fee paid to bank)
        //   (B) no payout: pot_after == pot_before + amount and bal_after == bal_before + amount
        // Note: we cannot directly read FEE_AMOUNT constant, so we use the numeric value 1 as it is part
        // of the intended contract behavior; this detects changes where fee is paid on payout path.

        assert(
            (reverted && pot_after == pot_before && bal_after == bal_before)
            || (
                !reverted && (
                    (pot_after == 0 && bal_before >= bal_after && (bal_before - bal_after) == 1)
                    || (pot_after == pot_before + amount && bal_after == bal_before + amount)
                )
            )
        );
    }

    // receive to accept refunds/payouts
    receive() external payable {}
}

